// Valida los datos de CAMBIO_ENTRENAMIENTO y depura los destinatarios (sin duplicados por
// correo, sin mayúsculas, y sin correos inválidos). Nunca lanza errores: devuelve
// { valido, detalle, destinatarios } y el nodo IF siguiente responde 202 o 400.
// "detalle" explica el primer problema y nunca incluye correos ni nombres.
const TIPOS = ['CREADO', 'MODIFICADO', 'CANCELADO'];
const MAX_DESTINATARIOS = 200;
const MAX_TEXTO = 120;
const MAX_MOTIVO = 500;
const RE_CORREO = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const RE_FECHA = /^\d{4}-\d{2}-\d{2}$/;
const RE_HORA = /^([01]\d|2[0-3]):[0-5]\d$/;

const esObjeto = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const vacio = (v) => v === undefined || v === null;
const textoValido = (v, max) => typeof v === 'string' && v.trim() !== '' && v.trim().length <= max;
const fechaValida = (v) =>
  typeof v === 'string' && RE_FECHA.test(v) && DateTime.fromISO(v, { zone: 'America/Bogota' }).isValid;
const horaValida = (v) => typeof v === 'string' && RE_HORA.test(v);

// Reglas de cada campo del entrenamiento; "anterior" usa las mismas.
const CAMPOS = {
  categoria: [(v) => textoValido(v, MAX_TEXTO), `es obligatorio (máximo ${MAX_TEXTO} caracteres)`],
  fecha: [fechaValida, 'debe ser una fecha con el formato AAAA-MM-DD'],
  horaInicio: [horaValida, 'debe tener el formato HH:mm (00:00 a 23:59)'],
  lugar: [(v) => textoValido(v, MAX_TEXTO), `es obligatorio (máximo ${MAX_TEXTO} caracteres)`],
  entrenador: [(v) => textoValido(v, MAX_TEXTO), `es obligatorio (máximo ${MAX_TEXTO} caracteres)`],
};

function validar(datos) {
  if (!TIPOS.includes(datos.tipoCambio)) return 'tipoCambio debe ser CREADO, MODIFICADO o CANCELADO';
  if (!esObjeto(datos.entrenamiento)) return 'falta el objeto entrenamiento';
  for (const [campo, [valido, regla]] of Object.entries(CAMPOS)) {
    if (!valido(datos.entrenamiento[campo])) return `entrenamiento.${campo} ${regla}`;
  }
  // "anterior" solo cuenta en MODIFICADO; con otro tipo se ignora sin validarlo.
  if (datos.tipoCambio === 'MODIFICADO' && !vacio(datos.anterior)) {
    if (!esObjeto(datos.anterior)) return 'anterior debe ser un objeto';
    for (const campo of ['fecha', 'horaInicio', 'lugar', 'entrenador']) {
      const [valido, regla] = CAMPOS[campo];
      if (!vacio(datos.anterior[campo]) && !valido(datos.anterior[campo])) return `anterior.${campo} ${regla}`;
    }
  }
  if (!vacio(datos.motivo) && (typeof datos.motivo !== 'string' || datos.motivo.trim().length > MAX_MOTIVO)) {
    return `motivo debe ser texto de máximo ${MAX_MOTIVO} caracteres`;
  }
  if (
    !Array.isArray(datos.destinatarios) ||
    datos.destinatarios.length < 1 ||
    datos.destinatarios.length > MAX_DESTINATARIOS
  ) {
    return `destinatarios debe tener entre 1 y ${MAX_DESTINATARIOS} elementos`;
  }
  return null;
}

function depurar(lista) {
  const vistos = new Set();
  const destinatarios = [];
  for (const d of lista) {
    if (!esObjeto(d) || typeof d.correo !== 'string') continue;
    const correo = d.correo.trim();
    if (correo.length > 254 || !RE_CORREO.test(correo)) continue;
    const clave = correo.toLowerCase();
    if (vistos.has(clave)) continue;
    vistos.add(clave);
    destinatarios.push({ correo, nombre: textoValido(d.nombre, MAX_TEXTO) ? d.nombre.trim() : '' });
  }
  return destinatarios;
}

let resultado;
try {
  const datos = $('Webhook').first().json.body.datos;
  const detalle = esObjeto(datos) ? validar(datos) : 'datos debe ser un objeto';
  const destinatarios = detalle ? [] : depurar(datos.destinatarios);
  if (detalle) {
    resultado = { valido: false, detalle, destinatarios };
  } else if (destinatarios.length === 0) {
    resultado = { valido: false, detalle: 'destinatarios no tiene ningún correo válido', destinatarios };
  } else {
    resultado = { valido: true, detalle: '', destinatarios };
  }
} catch (error) {
  resultado = { valido: false, detalle: 'datos tiene un formato inválido', destinatarios: [] };
}

return [{ json: resultado }];

// Arma un correo por destinatario con las plantillas n8n/plantillas/cambio-entrenamiento.*
// (copias abajo; si cambias la plantilla, actualiza también estas constantes).
// Los datos ya vienen validados por "Validar datos CAMBIO_ENTRENAMIENTO".
const PLANTILLA_HTML = "<!DOCTYPE html>\n<html lang=\"es\" xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<meta name=\"x-apple-disable-message-reformatting\">\n<meta name=\"color-scheme\" content=\"light\">\n<meta name=\"supported-color-schemes\" content=\"light\">\n<title>{{asunto}}</title>\n</head>\n<body style=\"margin:0; padding:0; background-color:#F7F8FA; -webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;\">\n<!-- Texto de vista previa (oculto en el cuerpo del correo) -->\n<div style=\"display:none; max-height:0; overflow:hidden; mso-hide:all; font-size:1px; line-height:1px; color:#F7F8FA;\">\n{{vistaPrevia}}\n</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color:#F7F8FA;\">\n  <tr>\n    <td align=\"center\" style=\"padding:32px 16px;\">\n      <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"max-width:560px; background-color:#FFFFFF; border:1px solid #E5E7EB; border-radius:12px;\">\n        <!-- Encabezado -->\n        <tr>\n          <td align=\"left\" style=\"background-color:#0F2C4C; border-radius:12px 12px 0 0; padding:24px 32px;\">\n            <span style=\"font-family:'Plus Jakarta Sans', Arial, Helvetica, sans-serif; font-size:22px; font-weight:700; color:#FFFFFF; letter-spacing:0.5px;\">Fut<span style=\"color:#3CB043;\">Data</span></span>\n          </td>\n        </tr>\n        <!-- Cuerpo -->\n        <tr>\n          <td align=\"left\" style=\"padding:32px 32px 8px 32px; font-family:'Plus Jakarta Sans', Arial, Helvetica, sans-serif; color:#1A2332;\">\n            <!-- Etiqueta del tipo de cambio -->\n            <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:0 0 20px 0;\">\n              <tr>\n                <td style=\"background-color:{{etiquetaFondo}}; border-radius:999px; padding:6px 14px; font-family:'Plus Jakarta Sans', Arial, Helvetica, sans-serif; font-size:13px; line-height:18px; font-weight:700; color:{{etiquetaTexto}};\">{{etiqueta}}</td>\n              </tr>\n            </table>\n            <p style=\"margin:0 0 16px 0; font-size:18px; font-weight:600; line-height:26px;\">{{saludo}}</p>\n            <p style=\"margin:0 0 24px 0; font-size:15px; line-height:24px; color:#4B5563;\">{{intro}}</p>\n          </td>\n        </tr>\n        <!-- Datos del entrenamiento -->\n        <tr>\n          <td style=\"padding:0 32px 24px 32px;\">\n            <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"border:1px solid #E5E7EB; border-radius:8px;\">\n{{filasDetalle}}\n            </table>\n          </td>\n        </tr>\n{{bloqueMotivo}}\n        <tr>\n          <td align=\"left\" style=\"padding:0 32px 32px 32px; font-family:'Plus Jakarta Sans', Arial, Helvetica, sans-serif; font-size:14px; line-height:22px; color:#4B5563;\">\n            Si tienes preguntas, comunícate con el entrenador o con el club.\n          </td>\n        </tr>\n        <!-- Pie -->\n        <tr>\n          <td align=\"center\" style=\"border-top:1px solid #E5E7EB; padding:20px 32px; font-family:'Plus Jakarta Sans', Arial, Helvetica, sans-serif; font-size:12px; line-height:18px; color:#4B5563;\">\n            Recibes este aviso porque estás registrado en la categoría {{categoria}} como entrenador, jugador o acudiente.<br>\n            Asociación Deportiva Prado Fútbol Club · FutData<br>\n            Este es un correo automático, por favor no lo respondas.\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>\n";
const PLANTILLA_TEXTO = "{{saludo}}\n\n{{intro}}\n\n{{detalle}}\n{{motivo}}\nSi tienes preguntas, comunícate con el entrenador o con el club.\n\n--\nRecibes este aviso porque estás registrado en la categoría {{categoria}}\ncomo entrenador, jugador o acudiente.\nAsociación Deportiva Prado Fútbol Club · FutData\nEste es un correo automático, por favor no lo respondas.\n";

const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
const DIAS_CORTOS = ['lun', 'mar', 'mié', 'jue', 'vie', 'sáb', 'dom'];
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const MESES_CORTOS = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
const TIPOS = {
  CREADO: { etiqueta: 'Nuevo entrenamiento', asunto: 'Nuevo entrenamiento', fondo: '#E8F7E8', texto: '#1F7A29' },
  MODIFICADO: { etiqueta: 'Entrenamiento modificado', asunto: 'Cambio en el entrenamiento', fondo: '#FEF3E2', texto: '#7A4B00' },
  CANCELADO: { etiqueta: 'Entrenamiento cancelado', asunto: 'Entrenamiento cancelado', fondo: '#FDECEA', texto: '#B3261E' },
};
const FUENTE = "font-family:'Plus Jakarta Sans', Arial, Helvetica, sans-serif;";

// Una sola línea, sin saltos (evita encabezados rotos en el asunto).
const limpiar = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const escapar = (v) =>
  limpiar(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
// fecha y horaInicio son hora local de Colombia; no se convierten.
const momento = (fecha, hora = '00:00') => DateTime.fromISO(`${fecha}T${hora}`, { zone: 'America/Bogota' });
const hora12 = (dt) => `${dt.hour % 12 || 12}:${String(dt.minute).padStart(2, '0')} ${dt.hour < 12 ? 'a. m.' : 'p. m.'}`;
const fechaLarga = (dt) => `${DIAS[dt.weekday - 1]} ${dt.day} de ${MESES[dt.month - 1]} de ${dt.year}`;
const fechaCorta = (dt) => `${DIAS_CORTOS[dt.weekday - 1]} ${dt.day} ${MESES_CORTOS[dt.month - 1]}`;
// Reemplaza {{marcador}} en una sola pasada: un texto de la petición con "{{...}}" no se vuelve a procesar.
const llenar = (plantilla, valores) => plantilla.replace(/\{\{(\w+)\}\}/g, (_, clave) => valores[clave] ?? '');

const datos = $('Webhook').first().json.body.datos;
const destinatarios = $input.first().json.destinatarios;
const tipo = datos.tipoCambio;
const e = datos.entrenamiento;
const anterior = tipo === 'MODIFICADO' && datos.anterior && typeof datos.anterior === 'object' ? datos.anterior : {};
const cambio = (campo) => anterior[campo] != null && limpiar(anterior[campo]) !== limpiar(e[campo]);
const actual = momento(e.fecha, e.horaInicio);
const categoria = limpiar(e.categoria);
const motivo = tipo === 'CREADO' ? '' : limpiar(datos.motivo);
const t = TIPOS[tipo];

// [etiqueta, valor actual, valor anterior (solo si cambió)]
const filas = [
  ['Categoría', categoria, null],
  ['Fecha', fechaLarga(actual), cambio('fecha') ? fechaLarga(momento(anterior.fecha)) : null],
  ['Hora', `${hora12(actual)}, hora de Colombia`, cambio('horaInicio') ? hora12(momento(e.fecha, anterior.horaInicio)) : null],
  ['Lugar', limpiar(e.lugar), cambio('lugar') ? limpiar(anterior.lugar) : null],
  ['Entrenador', limpiar(e.entrenador), cambio('entrenador') ? limpiar(anterior.entrenador) : null],
];
const hayCambios = filas.some((f) => f[2] !== null);

const filaHtml = ([etiqueta, valor, antes], i) => {
  const borde = i < filas.length - 1 ? ' border-bottom:1px solid #E5E7EB;' : '';
  const contenido =
    antes === null
      ? escapar(valor)
      : `<span style="font-size:12px; color:#4B5563;">Antes:</span> <span style="color:#4B5563; text-decoration:line-through;">${escapar(antes)}</span><br>` +
        `<span style="font-size:12px; color:#1F7A29;">Ahora:</span> <strong style="color:#1F7A29;">${escapar(valor)}</strong>`;
  return [
    '              <tr>',
    `                <td width="110" valign="top" style="padding:12px 16px;${borde} ${FUENTE} font-size:13px; line-height:22px; font-weight:600; color:#4B5563;">${etiqueta}</td>`,
    `                <td valign="top" style="padding:12px 16px;${borde}${antes === null ? '' : ' background-color:#E8F7E8;'} ${FUENTE} font-size:15px; line-height:22px; color:#1A2332;">${contenido}</td>`,
    '              </tr>',
  ].join('\n');
};
const filaTexto = ([etiqueta, valor, antes]) => `${`${etiqueta}:`.padEnd(12)}${valor}${antes === null ? '' : ` (antes: ${antes})`}`;

const intro = {
  CREADO: [`Se programó un nuevo entrenamiento para la categoría ${categoria}.`],
  MODIFICADO: hayCambios
    ? [
        `Cambiaron los datos del entrenamiento de la categoría ${categoria}. Lo que cambió aparece resaltado:`,
        `Cambiaron los datos del entrenamiento de la categoría ${categoria}. Lo que cambió muestra el valor anterior entre paréntesis:`,
      ]
    : [`Se actualizó el entrenamiento de la categoría ${categoria}. Estos son sus datos:`],
  CANCELADO: [`Se canceló el entrenamiento de la categoría ${categoria}. No se realizará en la fecha y hora indicadas:`],
}[tipo];
const introHtml = intro[0];
const introTexto = intro[1] ?? intro[0];

const bloqueMotivo = motivo
  ? [
      '        <tr>',
      '          <td style="padding:0 32px 24px 32px;">',
      '            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#FEF3E2; border-left:4px solid #F2A93B; border-radius:6px;">',
      '              <tr>',
      `                <td style="padding:16px; ${FUENTE} font-size:14px; line-height:22px; color:#7A4B00;">`,
      `                  <strong>Motivo:</strong> ${escapar(motivo)}`,
      '                </td>',
      '              </tr>',
      '            </table>',
      '          </td>',
      '        </tr>',
    ].join('\n')
  : '';

const asunto = `${t.asunto} ${categoria} · ${fechaCorta(actual)}, ${hora12(actual)}`;
const comunes = {
  asunto: escapar(asunto),
  vistaPrevia: escapar(`${t.etiqueta}: ${fechaLarga(actual)}, ${hora12(actual)}, ${limpiar(e.lugar)}.`),
  etiqueta: t.etiqueta,
  etiquetaFondo: t.fondo,
  etiquetaTexto: t.texto,
  intro: escapar(introHtml),
  filasDetalle: filas.map(filaHtml).join('\n'),
  bloqueMotivo,
  categoria: escapar(categoria),
};
const comunesTexto = {
  intro: introTexto,
  detalle: filas.map(filaTexto).join('\n'),
  motivo: motivo ? `\nMotivo: ${motivo}\n` : '',
  categoria,
};

return destinatarios.map((d) => ({
  json: {
    correo: d.correo,
    asunto,
    html: llenar(PLANTILLA_HTML, { ...comunes, saludo: d.nombre ? `Hola, ${escapar(d.nombre)}:` : 'Hola:' }),
    texto: llenar(PLANTILLA_TEXTO, { ...comunesTexto, saludo: d.nombre ? `Hola, ${limpiar(d.nombre)}:` : 'Hola:' }),
  },
}));

